def next_greater(a):
    """单调栈:返回每个位置右侧第一个『严格更大』的元素,无则 -1。
    栈里存『还没找到更大元素的下标』,对应的值从栈底到栈顶递减;
    遇到 a[i] 时,把栈顶所有比 a[i] 小的下标弹出——它们的答案就是 a[i]。"""
    n = len(a)
    res = [-1] * n
    stack = []                       # 存下标,a[stack] 自底向顶递减
    for i, x in enumerate(a):
        while stack and a[stack[-1]] < x:
            res[stack.pop()] = x     # 栈顶找到了它的下一个更大元素
        stack.append(i)
    return res
